59	                p -> new Object[] {id(p, "id"), p.get("name"), id(p, "clientId"),
60	                        p.getOrDefault("status", "ACTIVE"), Boolean.TRUE.equals(p.get("archived"))});
61	        seedTable(fixture, "contacts",
