69	                "INSERT INTO notes (id, target_type, target_id, note_text, noted_at) VALUES (?, ?, ?, ?, ?)",
70	                n -> new Object[] {id(n, "id"), n.get("targetType"), id(n, "targetId"), n.get("text"),
71	                        n.get("at")});
72	        // Notes are pre-seeded AND created through the API in the same spec, so the identity has to
73	        // continue past the seeded ids (a raw insert of an explicit id does not advance H2's
74	        // GENERATED BY DEFAULT sequence — the next app insert would otherwise collide on id=1).
75	        restartIdentity("notes");
76	        seedTable(fixture, "tags", "INSERT INTO tags (id, name) VALUES (?, ?)",
77	                t -> new Object[] {id(t, "id"), t.get("name")});
78	        seedTable(fixture, "projectTags",
79	                "INSERT INTO project_tags (project_id, tag_id) VALUES (?, ?)",
80	                pt -> new Object[] {id(pt, "projectId"), id(pt, "tagId")});
