87	        // to continue past the seeded ids (a raw insert of an explicit id does not advance H2's
88	        // GENERATED BY DEFAULT sequence — the next app insert would otherwise collide on id=1).
89	        restartIdentity("invoice_payments");
90	    }
91	
92	    /**
93	     * Seed invoices and, nested under each, its line items. An invoice's amount is the sum of its
94	     * lines' qty * unitPrice, so when a fixture lists {@code lineItems} the amount is derived from
95	     * them (the user no longer types one figure); a fixture may still give an explicit
96	     * {@code amount} instead (an invoice with no lines). One method rather than a plain seedTable
97	     * call because the line items live inside each invoice, keyed by the invoice's own id.
98	     */
99	    @SuppressWarnings("unchecked")
100	    private void seedInvoices(Map<String, Object> fixture) {
101	        List<Map<String, Object>> invoices = (List<Map<String, Object>>) fixture.get("invoices");
102	        if (invoices == null) {
103	            return;
104	        }
105	        for (Map<String, Object> invoice : invoices) {
106	            long invoiceId = id(invoice, "id");
107	            List<Map<String, Object>> lineItems =
108	                    (List<Map<String, Object>>) invoice.get("lineItems");
109	            double amount;
110	            if (invoice.get("amount") != null) {
111	                amount = ((Number) invoice.get("amount")).doubleValue();
112	            } else {
113	                amount = 0.0;
114	                if (lineItems != null) {
115	                    for (Map<String, Object> line : lineItems) {
116	                        amount += ((Number) line.get("qty")).doubleValue()
117	                                * ((Number) line.get("unitPrice")).doubleValue();
118	                    }
119	                }
120	            }
121	            jdbc.update("INSERT INTO invoices (id, project_id, amount, status, issued_date, due_date)"
122	                    + " VALUES (?, ?, ?, ?, ?, ?)",
123	                    invoiceId, id(invoice, "projectId"), amount,
124	                    invoice.getOrDefault("status", "DRAFT"), invoice.get("issuedDate"),
125	                    invoice.get("dueDate"));
126	            if (lineItems != null) {
127	                for (Map<String, Object> line : lineItems) {
128	                    jdbc.update("INSERT INTO invoice_line_items"
129	                            + " (id, invoice_id, description, qty, unit_price) VALUES (?, ?, ?, ?, ?)",
130	                            id(line, "id"), invoiceId, line.get("description"),
131	                            ((Number) line.get("qty")).intValue(),
132	                            ((Number) line.get("unitPrice")).doubleValue());
133	                }
134	            }
135	        }
136	    }
