138	    /**
139	     * Insert every row the fixture supplies under {@code key}, mapping each to the {@code sql}
140	     * parameters with {@code toParams}. Absent key = nothing to seed. One call per table keeps
141	     * seeding a new table a single additive line.
142	     */
143	    @SuppressWarnings("unchecked")
144	    private void seedTable(Map<String, Object> fixture, String key, String sql,
145	            Function<Map<String, Object>, Object[]> toParams) {
146	        List<Map<String, Object>> rows = (List<Map<String, Object>>) fixture.get(key);
147	        if (rows == null) {
148	            return;
149	        }
150	        for (Map<String, Object> row : rows) {
151	            // Explicit fixture id (JPA save() would ignore it — the spec asserts by these ids).
152	            jdbc.update(sql, toParams.apply(row));
153	        }
154	    }
155	
156	    /**
157	     * Continue a table's IDENTITY past the highest seeded id, so an API insert after seeding gets a
158	     * fresh id instead of colliding with a fixture row (H2 does not advance the sequence for the
159	     * explicit ids a JdbcTemplate seed inserts).
160	     */
161	    private void restartIdentity(String table) {
162	        Long max = jdbc.queryForObject("SELECT COALESCE(MAX(id), 0) FROM " + table, Long.class);
163	        jdbc.execute("ALTER TABLE " + table + " ALTER COLUMN id RESTART WITH " + (max + 1));
164	    }
165	
166	    /** Read a fixture field as a table id (JSON numbers arrive as {@link Number}). */
167	    private static long id(Map<String, Object> row, String key) {
168	        return ((Number) row.get(key)).longValue();
169	    }
170	}
